# 2026-05-12: Fixed _normalize_eap_edge to reuse _normalize_ac_node, ensuring consistent canonical edge names across methods.
"""Unified circuit discovery interface for K=3 methods."""

import re
import gc
from typing import Dict

from config import MVPConfig, MVP_CONFIG


def _normalize_eap_edge(edge_str: str) -> str:
    parts = edge_str.strip().split('->')
    if len(parts) == 2:
        src_raw = parts[0].strip().strip('<>')
        dst_raw = parts[1].strip()
        m = re.match(r'(.+)<([qkvQKV])>$', dst_raw)
        if m:
            dst_node, qkv = m.groups()
            dst_node = dst_node.strip('<>')
            return f'{_normalize_ac_node(src_raw)}->{_normalize_ac_node(dst_node)}.{qkv.lower()}'
        dst_raw = dst_raw.strip('<>')
        return f'{_normalize_ac_node(src_raw)}->{_normalize_ac_node(dst_raw)}'
    return edge_str.strip().strip('<>').lower()


def _normalize_ac_node(node_str: str) -> str:
    node_str = node_str.strip()
    low = node_str.lower().replace(' ', '_')
    if low in ('resid_start', 'resid_pre', 'input', 'embed'):
        return 'input'
    if low in ('resid_end', 'resid_post', 'logits', 'output'):
        return 'logits'
    m = re.match(r'(?:mlp[\s_]*|m)(\d+)$', node_str, re.IGNORECASE)
    if m:
        return f'm{m.group(1)}'
    m = re.match(r'A(\d+)\.(\d+)(?:\.([QKV]))?', node_str)
    if m:
        l, h, qkv = m.groups()
        r = f'a{l}.h{h}'
        if qkv:
            r += f'.{qkv.lower()}'
        return r
    return node_str.lower()


def _normalize_ac_edge(edge_str: str) -> str:
    parts = edge_str.split('->')
    if len(parts) == 2:
        return f'{_normalize_ac_node(parts[0])}->{_normalize_ac_node(parts[1])}'
    return edge_str.strip()


def _normalize_ifr_node(node_str: str) -> str:
    node_str = node_str.strip()
    if node_str == "hook_embed":
        return "input"
    m = re.match(r'blocks\.(\d+)\.attn\.hook_result\[(\d+)\]', node_str)
    if m:
        return f'a{m.group(1)}.h{m.group(2)}'
    m = re.match(r'blocks\.(\d+)\.hook_mlp_(out|in)', node_str)
    if m:
        return f'm{m.group(1)}'
    m = re.match(r'blocks\.(\d+)\.attn\.hook_([qkv])\[(\d+)\]', node_str)
    if m:
        return f'a{m.group(1)}.h{m.group(3)}.{m.group(2)}'
    return node_str.lower()


def _normalize_ifr_edge(edge_str: str) -> str:
    for sep in (' -> ', '->'):
        parts = edge_str.split(sep)
        if len(parts) == 2:
            return f'{_normalize_ifr_node(parts[0])}->{_normalize_ifr_node(parts[1])}'
    return edge_str.strip()


_NORMALIZERS = {
    "eap_ig": _normalize_eap_edge,
    "edge_pruning": _normalize_ac_edge,
    "acdc": _normalize_ac_edge,
    "ifr": _normalize_ifr_edge,
}


def normalize_edge_names(scores: Dict[str, float], method: str) -> Dict[str, float]:
    normalizer = _NORMALIZERS.get(method, lambda x: x)
    return {normalizer(k): v for k, v in scores.items()}


def run_eap_ig(model, dataloader, metric, ig_steps=5, config=MVP_CONFIG):
    """Run EAP-IG attribution."""
    from eap.graph import Graph
    from eap.attribute import attribute

    graph = Graph.from_model(model)
    attribute(model, graph, dataloader, metric, method="EAP-IG-inputs", ig_steps=ig_steps)

    raw_scores = {}
    for name, edge in graph.edges.items():
        raw_scores[name] = float(edge.score)

    return normalize_edge_names(raw_scores, "eap_ig")


def _prune_scores_to_dict(prune_scores, model_edges):
    edge_scores = {}
    for edge in model_edges:
        dest_key = edge.dest.module_name
        if dest_key in prune_scores:
            try:
                score = float(prune_scores[dest_key][edge.patch_idx])
                edge_scores[edge.name] = score
            except (IndexError, KeyError, RuntimeError):
                continue
    return edge_scores


def run_edge_pruning(ac_task, config=MVP_CONFIG):
    """Run mask gradient (Edge Pruning proxy)."""
    from auto_circuit.prune_algos.mask_gradient import mask_gradient_prune_scores

    prune_scores = mask_gradient_prune_scores(
        model=ac_task.model,
        dataloader=ac_task.train_loader,
        official_edges=None,
        grad_function="logit",
        answer_function="avg_diff",
        integrated_grad_samples=10,
    )

    raw_scores = _prune_scores_to_dict(prune_scores, ac_task.model.edges)
    return normalize_edge_names(raw_scores, "edge_pruning")


def run_acdc(ac_task, config=MVP_CONFIG):
    """Run ACDC via auto_circuit. Output: inf=retained edge, finite=pruning threshold (tao)."""
    from auto_circuit.prune_algos.ACDC import acdc_prune_scores

    prune_scores = acdc_prune_scores(
        model=ac_task.model,
        dataloader=ac_task.train_loader,
        official_edges=None,
        tao_exps=[-2],
    )

    raw_scores = _prune_scores_to_dict(prune_scores, ac_task.model.edges)
    return normalize_edge_names(raw_scores, "acdc")


def run_ifr(model, dataset, metric=None, config=MVP_CONFIG):
    """Run IFR attribution (TransformerLens model)."""
    from ifr_discovery import run_ifr as _run_ifr_tl
    raw_scores = _run_ifr_tl(model, dataset, metric)
    return normalize_edge_names(raw_scores, "ifr")


def run_ifr_hf(model, dataset, metric_fn=None, threshold=0.1, device="cuda"):
    """Run IFR attribution (HuggingFace model)."""
    from ifr_scoring import compute_ifr_edges
    return compute_ifr_edges(model, dataset, metric_fn, threshold=threshold, device=device)


def _verify_edge_normalization():
    test_pairs = [
        ('input->a0.h0<q>', 'Resid Start->A0.0.Q'),
        ('a0.h0->m0',       'A0.0->MLP 0'),
        ('m0->a1.h3<k>',    'MLP 0->A1.3.K'),
        ('a9.h9->logits',   'A9.9->Resid End'),
    ]
    for eap_edge, ac_edge in test_pairs:
        eap_norm = _normalize_eap_edge(eap_edge)
        ac_norm = _normalize_eap_edge(ac_edge)
        assert eap_norm == ac_norm, f"MISMATCH: {eap_edge!r} -> {eap_norm!r} vs {ac_edge!r} -> {ac_norm!r}"

    ifr_test_pairs = [
        ('hook_embed -> blocks.0.attn.hook_q[0]', 'input->a0.h0.q'),
        ('blocks.1.attn.hook_result[3] -> blocks.2.hook_mlp_in', 'a1.h3->m2'),
        ('blocks.0.hook_mlp_out -> blocks.1.attn.hook_v[5]', 'm0->a1.h5.v'),
    ]
    for ifr_edge, expected in ifr_test_pairs:
        result = _normalize_ifr_edge(ifr_edge)
        assert result == expected, f"IFR MISMATCH: {ifr_edge!r} -> {result!r}, expected {expected!r}"

    print("EDGE_NORM_VERIFY: all assertions passed (incl. IFR)")


if __name__ == "__main__":
    _verify_edge_normalization()
